INSERT INTO ghostdesk.case_versions(version_id, case_id, package, published) VALUES ('demo-0317-v6', 'demo-0317', $case${"schemaVersion":1,"engineVersion":"ghostdesk-core-1","caseId":"demo-0317","versionId":"demo-0317-v6","title":"03:17에 멈춘 전송","description":"03:17 전송 기록 뒤 사라진 작업 목록. 야간 근무자로서 유출 여부와 담당자의 행방을 확인하고, 보존된 사본으로 목록을 복구하세요.","estimatedMinutes":55,"contentWarning":"실종을 암시하는 허구의 이야기. 공포 이미지·점프 스케어 없음.","files":[{"id":"f-handover","type":"TEXT","title":"인수인계.txt","parentId":null,"visible":true,"clueId":"c-clock","text":"03:17 전송 기록 뒤 사라진 작업 목록. 야간 근무자로서 유출 여부와 담당자의 행방을 확인하고, 보존된 사본으로 목록을 복구하세요.\n\n담당자가 남긴 메모\n기록 담당 윤서에게 연락이 닿지 않고 작업 목록도 비었습니다. 저는 야간 기록 검토를 맡은 다음 근무자입니다. 외부 유출 여부를 가리고, 남은 자료를 안전하게 복구해야 합니다.\n\n업무 폴더에는 담당자가 기록을 대조해 정한 암호가 걸려 있습니다. 암호 규칙은 인계 메모와 각 업무 기록의 끝에 적어 두었습니다. 한 번 연 기록도 지우지 마세요.\n\n「업무 자료」 폴더 암호: 마지막 외부 전송 요청의 실제 시각을 시·분 네 자리로. PC 표시와 실제 시각은 다르니 동시 측정 기록으로 보정해 주세요."},{"id":"f-chat","type":"CHAT_LINK","title":"메신저","parentId":null,"visible":true,"text":""},{"id":"f-photo","type":"TEXT","title":"시계_대조기록.txt","parentId":null,"visible":true,"text":"같은 순간에 옮겨 적은 표시 시각\n벽시계 03:10\n기록용 PC 03:17\n점검 구간에 오차는 일정했습니다.","clueId":"c-photo"},{"id":"trash","type":"FOLDER","title":"휴지통","parentId":null,"visible":true,"text":"삭제된 기록도 흔적을 남깁니다."},{"id":"f-queue","type":"TEXT","title":"transfer_queue.log","parentId":"trash","visible":true,"clueId":"c-queue","text":"ARCHIVE NODE / OUTBOUND QUEUE\n──────────────────────────\n시각 기준: 기록용 PC\n\n[03:17:00] SEND_REQUEST\n요청 ID      : TX-0917\n목적지       : EXTERNAL_ARCHIVE\n상태         : QUEUED\n완료 시각    : —\n\nQUEUED = 승인 대기열 등록\n전송 완료는 별도 영수증에서 확인합니다.\n──────────────────────────\n이 로그는 요청 사실만 기록합니다."},{"id":"f-receipt","type":"TEXT","title":"전송_처리_영수증.txt","parentId":"demo-0317-stage-5","visible":false,"clueId":"c-receipt","text":"OUTBOUND TRANSFER RECEIPT\n──────────────────────────\n요청 ID      : TX-0917\n승인 처리    : CANCELLED\n최종 상태    : 전송 승인 취소\n전송 완료    : 0건\n외부 전송량  : 0 bytes\n\n승인이 취소되어 대기열의 요청은 실행되지 않았습니다.\n\n이 영수증의 요청 ID와 큐 로그의 요청 ID를 대조하세요."},{"id":"demo-0317-scene","type":"IMAGE","title":"연구실_점검사진","parentId":null,"visible":true,"text":"점검 담당자가 남긴 현장 사진.","assetId":"lab","alt":"야간 연구실의 책상과 두 컴퓨터, 기록 보관 장치.","observations":[{"label":"촬영 시각","text":"점검 촬영: 벽시계 기준 03:20. 두 컴퓨터와 보관 장치, 분리된 연결선이 보입니다."},{"label":"시계 대조표","text":"동시 측정 / 벽시계 03:10 / 기록용 PC 03:17. 사진 속 작은 문자 대신 점검표에 옮긴 측정값입니다."}]},{"id":"demo-0317-stage-1","type":"FOLDER","title":"업무 자료","parentId":null,"visible":true,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","puzzleId":"demo-0317-p1-v6"},{"id":"demo-0317-record-2","type":"TEXT","title":"요청_연결하기.txt","parentId":null,"visible":false,"text":"분리된 접수표 / 시각은 모두 PC 기준\n\n접수표 A · TX-0916 · 03:16:00 · 외부 보관소\n접수표 B · TX-0917 · 03:17:00 · 내부 복제본\n접수표 C · TX-0917 · 03:17:00 · 외부 보관소\n\n한 요청을 외부 전송과 내부 복제에 각각 사용한 기록입니다. 요청 번호와 목적지가 모두 같은 접수표를 찾아야 합니다.\n\n접수 보관 번호: A=4621, B=7158, C=8306. 행의 문자 대신 보관 번호를 사용합니다.\n\n「접수 내역」 폴더 암호: 큐와 요청 번호·목적지가 모두 같은 접수표의 보관 번호 네 자리 뒤에, 그 요청의 실제 시각 네 자리를 붙입니다.","clueId":"demo-0317-record-clue-2"},{"id":"demo-0317-stage-2","type":"FOLDER","title":"접수 내역","parentId":null,"visible":false,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","puzzleId":"demo-0317-p2-v6"},{"id":"demo-0317-record-3","type":"TEXT","title":"처리_순서_복원.txt","parentId":null,"visible":false,"text":"처리 단편 / 모두 같은 PC 시각\n\n단편 1 · 03:17:09 · 승인 취소 접수\n단편 2 · 03:17:00 · 요청 생성\n단편 3 · 03:17:11 · 처리 내역 보관\n단편 4 · 03:17:02 · 승인 대기 등록\n\n사진은 03:20 점검 때 촬영되었습니다. 사진 속 선의 연결 상태만으로 그 이전 작업을 판단할 수는 없습니다.\n\n「작업 기록」 폴더 암호: 요청 생성부터 승인 취소 접수까지 걸린 초입니다. 대기 등록부터가 아닙니다.","clueId":"demo-0317-record-clue-3"},{"id":"demo-0317-stage-3","type":"FOLDER","title":"작업 기록","parentId":null,"visible":false,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","puzzleId":"demo-0317-p3-v6"},{"id":"demo-0317-record-4","type":"TEXT","title":"전송량_대조.txt","parentId":null,"visible":false,"text":"네트워크 계량기 / 03:16:50 → 03:17:20\n\n외부 회선 누적량: 8192 → 8192 바이트\n내부 복제 누적량: 4096 → 6144 바이트\n\n두 계량기는 서로 다른 회선입니다. 누적량은 초기화되지 않았습니다. 해당 구간에 다른 외부 작업은 없었습니다.\n\n「장비 관리」 폴더 암호: 내부 복제 증가량-외부 전송 증가량. 누적값 자체가 아니라 이번 작업의 바이트 수를 씁니다. 예: 128-64.","clueId":"demo-0317-record-clue-4"},{"id":"demo-0317-stage-4","type":"FOLDER","title":"장비 관리","parentId":null,"visible":false,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","puzzleId":"demo-0317-p4-v6"},{"id":"demo-0317-record-5","type":"TEXT","title":"최종_영수증_찾기.txt","parentId":null,"visible":false,"text":"보관소 영수증 색인\n\nA · TX-0917 · 외부 보관소 · 완료 1건 · 2048바이트\nB · TX-0917 · 외부 보관소 · 승인 취소 · 0바이트\nC · TX-0916 · 외부 보관소 · 승인 취소 · 0바이트\n\n선택한 색인을 원본 영수증과 대조합니다.\n\n영수증 보관 키: A=5132, B=9274, C=6801. 상태와 실제 전송량이 모두 맞는 한 건만 유효합니다.\n\n「전송 내역」 폴더 암호: 검증된 영수증의 보관 키-요청이 취소되기까지 걸린 초. 큐 번호·목적지·계량기까지 맞는 영수증만 사용합니다.","clueId":"demo-0317-record-clue-5"},{"id":"demo-0317-stage-5","type":"FOLDER","title":"전송 내역","parentId":null,"visible":false,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","puzzleId":"demo-0317-p5-v6"},{"id":"demo-0317-record-6a","type":"TEXT","title":"이관_신청서.txt","parentId":null,"text":"윤서의 내부 보존 신청 / 03:09 실제 시각\n\n요청 TX-0917 · 내용 2048바이트 · 내용 식별값 7C21. 내부 복사 작업은 외부 전송과 별도로 기록한다. 같은 파일 이름을 가진 시험용 자료는 식별값이 다르다.\n\n“작업실 PC를 비우기 전에 자료실 보존함으로 사본 하나를 남겨 둔다.”\n\n「보관 자료」 폴더 암호: 이관 신청과 일치하는 보관 사본의 내용 식별값-내부 계량기의 증가 바이트 수. 사본의 이름만으로 결정하지 않습니다.","visible":false,"clueId":"demo-0317-clue-6a"},{"id":"demo-0317-record-6b","type":"TEXT","title":"보관함_인덱스.txt","parentId":null,"text":"03:20 내부 보관함 목록 / 이미지 원문\n\nA / TX-0917 / 2048바이트 / 7C21\nB / TX-0917 / 2048바이트 / 9A06\nC / TX-0920 / 2048바이트 / 7C21\n\n세 항목의 화면상 파일 이름은 모두 야간기록이다. 위 식별값은 이 사건에서 내용을 구분하는 검증 코드이며 사람의 신원을 뜻하지 않는다.","visible":false,"clueId":"demo-0317-clue-6b"},{"id":"demo-0317-stage-6","type":"FOLDER","title":"보관 자료","parentId":null,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","visible":false,"puzzleId":"demo-0317-p6-v6"},{"id":"demo-0317-record-7a","type":"TEXT","title":"자료실_출입표.log","parentId":null,"text":"자료실 입구 카드 단말\n\n표시 03:17:00 / 카드 Y-04 / 입장 인식\n표시 03:26:00 / 카드 M-02 / 입장 인식\n\n카드 대여 여부와 실제 인계는 별도 서명부에서 확인한다. 이 기록은 PC가 아니라 자료실 입구 단말이 남겼다.","visible":false,"clueId":"demo-0317-clue-7a"},{"id":"demo-0317-record-7b","type":"TEXT","title":"장비별_시계점검.txt","parentId":null,"text":"같은 기준시각 03:00:00에서 읽은 값\n\n기준 시계 03:00:00\n작업실 PC 03:07:00\n자료실 입구 단말 03:05:00\n\n그날 점검 구간에는 각 오차가 일정했다. 카드 Y-04는 윤서, M-02는 민재에게 발급됐다. PC의 오차를 다른 장비에 그대로 적용하지 않는다.\n\n「출입 관리」 폴더 암호: 윤서 카드의 실제 입장 시각 네 자리-외부 요청의 실제 시각부터 입장까지 지난 분. 장비별 오차를 각각 적용합니다.","visible":false,"clueId":"demo-0317-clue-7b"},{"id":"demo-0317-stage-7","type":"FOLDER","title":"출입 관리","parentId":null,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","visible":false,"puzzleId":"demo-0317-p7-v6"},{"id":"demo-0317-record-8a","type":"TEXT","title":"보존_조각.log","parentId":null,"text":"같은 사본 7C21의 작업 조각\n\n조각 1 / PC 03:17:12 / 복사 완료\n조각 2 / 기준 03:13:00 / 자료실 인수\n조각 3 / 기준 03:10:03 / 내용 검증\n조각 4 / PC 03:17:18 / 운반함 봉인","visible":false,"clueId":"demo-0317-clue-8a"},{"id":"demo-0317-record-8b","type":"TEXT","title":"시계_적용표.txt","parentId":null,"text":"작업 조각을 읽는 법\n\nPC 표시는 기준시각보다 7분 빠르다. 기준 표시는 보정하지 않는다. 복사 완료와 운반함 봉인은 PC가 썼고, 내용 검증과 인수는 독립 기록계가 썼다.\n\n운반함은 종이 문서를 넣는 상자가 아니라 내부 저장 장치를 옮기는 봉인함이다. 외부 전송 큐와 혼동하지 않는다.\n\n「파일 정리」 폴더 암호: 내용 검증을 시작한 실제 시각-자료실에서 인수한 실제 시각. 각각 시·분·초 여섯 자리로 적습니다. 중간 조각도 보정해 순서가 이어지는지 확인하세요.","visible":false,"clueId":"demo-0317-clue-8b"},{"id":"demo-0317-stage-8","type":"FOLDER","title":"파일 정리","parentId":null,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","visible":false,"puzzleId":"demo-0317-p8-v6"},{"id":"demo-0317-record-9a","type":"TEXT","title":"인계_서명부.txt","parentId":null,"text":"A / 03:13 / 7C21 / 인계 민재 · 인수 윤서 / 시험 양식\nB / 03:13 / 9A06 / 인계 윤서 · 인수 보존 담당 / 확정\nC / 03:13 / 7C21 / 인계 윤서 · 인수 보존 담당 / 확정\n\n확정 항목만 보존 담당자가 대면 확인한 문서다.\n\n문서 보관 키: A=5021, B=7736, C=9418.","visible":false,"clueId":"demo-0317-clue-9a"},{"id":"demo-0317-record-9b","type":"TEXT","title":"양식_상태설명.txt","parentId":null,"text":"시험 양식은 연습용 이름을 자동으로 채운다. 실제 인계의 근거로 사용하지 않는다. 확정 문서라도 내용 식별값이 다르면 다른 사본의 기록이다.\n\n윤서의 카드 입장 시각은 이동 가능성을 설명하지만, 해당 사본을 누가 넘겼는지는 이 서명부와 보존 조각을 함께 대조해야 한다.\n\n「인수인계」 폴더 암호: 해당 사본의 확정 인계 문서 키-윤서의 실제 입장부터 인계까지 지난 분. 시험 문서와 다른 사본은 제외합니다.","visible":false,"clueId":"demo-0317-clue-9b"},{"id":"demo-0317-stage-9","type":"FOLDER","title":"인수인계","parentId":null,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","visible":false,"puzzleId":"demo-0317-p9-v6"},{"id":"demo-0317-record-10a","type":"TEXT","title":"목록_필터설정.txt","parentId":null,"text":"작업 목록 설정\n\n표시: 처리 중 항목만\n숨김: 보존 인수 확정 항목\n03:14 새로고침 결과: TX-0917 표시 대상에서 제외\n\n이 설정은 화면 목록만 바꾸며 저장 자료를 지우거나 외부로 보내지 않는다.","visible":false,"clueId":"demo-0317-clue-10a"},{"id":"demo-0317-record-10b","type":"TEXT","title":"보존_조회회신.txt","parentId":null,"text":"보존 담당 / 03:25 기준시각\n\n보관함 조회는 성공했지만 작업 목록 복구는 아직 승인되지 않았습니다. 윤서는 자료실에서 훼손 문서를 복구 중입니다. 같은 이름의 시험 사본을 연결하지 않도록, 초반 전송 기록부터 다시 대조해 복구 요청을 작성해 주세요.\n\n복구 동작표\nVIEW: 보존된 사본을 작업 목록에 다시 연결\nSEND: 사본을 외부로 전송\nPURGE: 보존 사본 제거\n\n원본 보존과 외부 전송 금지가 이번 인계 조건입니다. 승인하면 VIEW로 연결한 목록만 복원되며 보존 원본은 그대로 남습니다.\n\n「백업」 폴더 암호: 실행할 동작-보존 사본 식별값-최초 요청의 실제 시각 네 자리-검증된 외부 전송 바이트 수. 예전 기록을 다시 대조한 이 요청이 백업 복구 승인입니다.","visible":false,"clueId":"demo-0317-clue-10b"},{"id":"demo-0317-stage-10","type":"FOLDER","title":"백업","parentId":null,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","visible":false,"puzzleId":"demo-0317-p10-v6"}],"clues":[{"id":"c-clock","title":"인수인계.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"c-photo","title":"시계_대조기록.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"c-queue","title":"transfer_queue.log","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"c-receipt","title":"전송_처리_영수증.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"demo-0317-record-clue-2","title":"요청_연결하기.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"demo-0317-record-clue-3","title":"처리_순서_복원.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"demo-0317-record-clue-4","title":"전송량_대조.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"demo-0317-record-clue-5","title":"최종_영수증_찾기.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"demo-0317-clue-6a","title":"이관_신청서.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"demo-0317-clue-6b","title":"보관함_인덱스.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"demo-0317-clue-7a","title":"자료실_출입표.log","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"demo-0317-clue-7b","title":"장비별_시계점검.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"demo-0317-clue-8a","title":"보존_조각.log","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"demo-0317-clue-8b","title":"시계_적용표.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"demo-0317-clue-9a","title":"인계_서명부.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"demo-0317-clue-9b","title":"양식_상태설명.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"demo-0317-clue-10a","title":"목록_필터설정.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"demo-0317-clue-10b","title":"보존_조회회신.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."}],"puzzles":[{"id":"demo-0317-p1-v6","title":"업무 자료의 인계 규칙에 맞춰 기록을 대조하세요.","answer":"0310","ignoreCase":true,"hints":["「업무 자료」 폴더 암호: 마지막 외부 전송 요청의 실제 시각을 시·분 네 자리로. PC 표시와 실제 시각은 다르니 동시 측정 기록으로 보정해 주세요.","동시 측정에서 PC는 7분 빠릅니다. PC의 03:17 요청을 벽시계 기준으로 바꾸세요.","정답: 0310"],"stageTitle":"업무 자료","evidenceIds":["f-handover","f-photo","f-queue"],"inputMode":"text"},{"id":"demo-0317-p2-v6","title":"접수 내역의 인계 규칙에 맞춰 기록을 대조하세요.","answer":"83060310","ignoreCase":true,"hints":["「접수 내역」 폴더 암호: 큐와 요청 번호·목적지가 모두 같은 접수표의 보관 번호 네 자리 뒤에, 그 요청의 실제 시각 네 자리를 붙입니다.","내부 복제 접수는 제외합니다. 외부 TX-0917에 해당하는 C의 보관 번호와 앞서 보정한 요청 시각을 연결하세요.","정답: 83060310"],"stageTitle":"접수 내역","evidenceIds":["demo-0317-record-2","f-queue","f-photo"],"inputMode":"text"},{"id":"demo-0317-p3-v6","title":"작업 기록의 인계 규칙에 맞춰 기록을 대조하세요.","answer":"9","ignoreCase":true,"hints":["「작업 기록」 폴더 암호: 요청 생성부터 승인 취소 접수까지 걸린 초입니다. 대기 등록부터가 아닙니다.","같은 PC 시계이므로 차이에는 7분 보정이 필요 없습니다. 03:17:00부터 03:17:09까지입니다.","정답: 9"],"stageTitle":"작업 기록","evidenceIds":["demo-0317-record-3","f-queue"],"inputMode":"text"},{"id":"demo-0317-p4-v6","title":"장비 관리의 인계 규칙에 맞춰 기록을 대조하세요.","answer":"2048-0","ignoreCase":true,"hints":["「장비 관리」 폴더 암호: 내부 복제 증가량-외부 전송 증가량. 누적값 자체가 아니라 이번 작업의 바이트 수를 씁니다. 예: 128-64.","내부는 6144−4096, 외부는 8192−8192입니다. 연결선 사진만으로 전송량을 단정하지 마세요.","정답: 2048-0"],"stageTitle":"장비 관리","evidenceIds":["demo-0317-record-4","demo-0317-record-3"],"inputMode":"text"},{"id":"demo-0317-p5-v6","title":"전송 내역의 인계 규칙에 맞춰 기록을 대조하세요.","answer":"9274-9","ignoreCase":true,"hints":["「전송 내역」 폴더 암호: 검증된 영수증의 보관 키-요청이 취소되기까지 걸린 초. 큐 번호·목적지·계량기까지 맞는 영수증만 사용합니다.","완료 2048바이트라는 A는 외부 계량기와 충돌합니다. B의 키에 생성→취소의 9초를 연결하세요.","정답: 9274-9"],"stageTitle":"전송 내역","evidenceIds":["demo-0317-record-5","f-queue","demo-0317-record-3","demo-0317-record-4"],"inputMode":"text"},{"id":"demo-0317-p6-v6","title":"보관 자료의 인계 규칙에 맞춰 기록을 대조하세요.","answer":"7C21-2048","ignoreCase":true,"stageTitle":"보관 자료","evidenceIds":["demo-0317-record-6a","demo-0317-record-6b","demo-0317-record-4"],"inputMode":"text","hints":["「보관 자료」 폴더 암호: 이관 신청과 일치하는 보관 사본의 내용 식별값-내부 계량기의 증가 바이트 수. 사본의 이름만으로 결정하지 않습니다.","요청 TX-0917과 내용 식별값, 크기를 모두 대조합니다. 보관 사본 크기가 내부 회선의 증가량과도 같아야 합니다.","정답: 7C21-2048"]},{"id":"demo-0317-p7-v6","title":"출입 관리의 인계 규칙에 맞춰 기록을 대조하세요.","answer":"0312-2","ignoreCase":true,"stageTitle":"출입 관리","evidenceIds":["demo-0317-record-7b","demo-0317-record-7a","f-queue","f-photo"],"inputMode":"text","hints":["「출입 관리」 폴더 암호: 윤서 카드의 실제 입장 시각 네 자리-외부 요청의 실제 시각부터 입장까지 지난 분. 장비별 오차를 각각 적용합니다.","자료실 단말 03:17은 5분 빠르므로 03:12입니다. PC 요청의 실제 03:10과는 2분 차이입니다.","정답: 0312-2"]},{"id":"demo-0317-p8-v6","title":"파일 정리의 인계 규칙에 맞춰 기록을 대조하세요.","answer":"031003-031300","ignoreCase":true,"stageTitle":"파일 정리","evidenceIds":["demo-0317-record-8b","demo-0317-record-8a","f-photo"],"inputMode":"text","hints":["「파일 정리」 폴더 암호: 내용 검증을 시작한 실제 시각-자료실에서 인수한 실제 시각. 각각 시·분·초 여섯 자리로 적습니다. 중간 조각도 보정해 순서가 이어지는지 확인하세요.","검증은 기준 03:10:03, 복사는 보정 후 03:10:12, 봉인은 03:10:18, 인수는 03:13:00입니다.","정답: 031003-031300"]},{"id":"demo-0317-p9-v6","title":"인수인계의 인계 규칙에 맞춰 기록을 대조하세요.","answer":"9418-1","ignoreCase":true,"stageTitle":"인수인계","evidenceIds":["demo-0317-record-9b","demo-0317-record-9a","demo-0317-record-6a","demo-0317-record-7a","demo-0317-record-7b"],"inputMode":"text","hints":["「인수인계」 폴더 암호: 해당 사본의 확정 인계 문서 키-윤서의 실제 입장부터 인계까지 지난 분. 시험 문서와 다른 사본은 제외합니다.","7C21을 윤서가 인계한 확정 문서는 C입니다. 실제 입장은 03:12, 인계는 03:13입니다.","정답: 9418-1"]},{"id":"demo-0317-p10-v6","title":"백업의 인계 규칙에 맞춰 기록을 대조하세요.","answer":"VIEW-7C21-0310-0","ignoreCase":true,"stageTitle":"백업","evidenceIds":["demo-0317-record-10b","demo-0317-record-10a","demo-0317-record-6a","demo-0317-record-6b","f-queue","f-photo","demo-0317-record-4"],"inputMode":"text","hints":["「백업」 폴더 암호: 실행할 동작-보존 사본 식별값-최초 요청의 실제 시각 네 자리-검증된 외부 전송 바이트 수. 예전 기록을 다시 대조한 이 요청이 백업 복구 승인입니다.","필터 때문에 숨은 사본을 VIEW로 연결합니다. 7C21 사본, 실제 요청 03:10, 외부 증가량 0을 초기 기록에서 다시 검증하세요.","정답: VIEW-7C21-0310-0"]}],"messages":[{"id":"m-1","author":"민재","time":"03:24","text":"아직 연구실이야? 기록 담당자에게 연락이 안 돼.","initial":true},{"id":"m-2","author":"민재","time":"03:25","text":"난 03:10에는 이미 밖에 있었어. 근데 컴퓨터에 전송 기록이 남아 있다며?","initial":true},{"id":"m-3","author":"민재","time":"03:27","text":"혹시 그거 실제로 전송된 게 맞아? 대기열에 들어간 것과 완료된 건 다를 수 있어.","initial":false},{"id":"m-4","author":"민재","time":"03:28","text":"보관함이 열렸구나. 영수증의 요청 번호도 꼭 확인해 줘.","initial":false},{"id":"demo-0317-chapter-6","author":"기록 담당 윤서","time":"03:28","text":"외부 전송은 없었군요. 그런데 내부 보관함에는 파일 이름이 같은 복사본이 셋 남아 있어요. 제가 남긴 이관 신청과 맞는 자료가 무엇인지 확인해 주세요. 이름이 같아도 같은 파일은 아닙니다.","initial":false},{"id":"demo-0317-chapter-8","author":"기록 담당 윤서","time":"03:29","text":"제 출입 카드와 실제 인계 서명은 따로 확인해 주세요. 카드가 찍혔다는 사실만으로 누가 안에 있었는지 단정할 수는 없어요.","initial":false},{"id":"demo-0317-chapter-complete","author":"기록 담당 윤서","time":"03:30","text":"백업 복구 요청이 승인됐습니다. 7C21 사본이 작업 목록에 다시 나타났고 외부 전송은 실행되지 않았습니다.","initial":false}],"rules":[{"id":"demo-0317-advance-1","priority":1,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"demo-0317-p1-v6"},"then":[{"type":"REVEAL_FILE","id":"demo-0317-stage-2"},{"type":"REVEAL_FILE","id":"demo-0317-record-2"},{"type":"APPEND_MESSAGE","id":"m-3"}]},{"id":"demo-0317-advance-2","priority":2,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"demo-0317-p2-v6"},"then":[{"type":"REVEAL_FILE","id":"demo-0317-stage-3"},{"type":"REVEAL_FILE","id":"demo-0317-record-3"}]},{"id":"demo-0317-advance-3","priority":3,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"demo-0317-p3-v6"},"then":[{"type":"REVEAL_FILE","id":"demo-0317-stage-4"},{"type":"REVEAL_FILE","id":"demo-0317-record-4"}]},{"id":"demo-0317-advance-4","priority":4,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"demo-0317-p4-v6"},"then":[{"type":"REVEAL_FILE","id":"demo-0317-stage-5"},{"type":"REVEAL_FILE","id":"demo-0317-record-5"}]},{"id":"demo-0317-advance-5","priority":5,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"demo-0317-p5-v6"},"then":[{"type":"REVEAL_FILE","id":"f-receipt"},{"type":"APPEND_MESSAGE","id":"m-4"},{"type":"REVEAL_FILE","id":"demo-0317-stage-6"},{"type":"REVEAL_FILE","id":"demo-0317-record-6a"},{"type":"REVEAL_FILE","id":"demo-0317-record-6b"},{"type":"APPEND_MESSAGE","id":"demo-0317-chapter-6"}]},{"id":"demo-0317-advance-6","priority":6,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"demo-0317-p6-v6"},"then":[{"type":"REVEAL_FILE","id":"demo-0317-stage-7"},{"type":"REVEAL_FILE","id":"demo-0317-record-7a"},{"type":"REVEAL_FILE","id":"demo-0317-record-7b"}]},{"id":"demo-0317-advance-7","priority":7,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"demo-0317-p7-v6"},"then":[{"type":"REVEAL_FILE","id":"demo-0317-stage-8"},{"type":"REVEAL_FILE","id":"demo-0317-record-8a"},{"type":"REVEAL_FILE","id":"demo-0317-record-8b"},{"type":"APPEND_MESSAGE","id":"demo-0317-chapter-8"}]},{"id":"demo-0317-advance-8","priority":8,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"demo-0317-p8-v6"},"then":[{"type":"REVEAL_FILE","id":"demo-0317-stage-9"},{"type":"REVEAL_FILE","id":"demo-0317-record-9a"},{"type":"REVEAL_FILE","id":"demo-0317-record-9b"}]},{"id":"demo-0317-advance-9","priority":9,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"demo-0317-p9-v6"},"then":[{"type":"REVEAL_FILE","id":"demo-0317-stage-10"},{"type":"REVEAL_FILE","id":"demo-0317-record-10a"},{"type":"REVEAL_FILE","id":"demo-0317-record-10b"}]},{"id":"demo-0317-advance-10","priority":10,"once":true,"when":{"type":"ALL","conditions":[{"type":"PUZZLE_SOLVED","id":"demo-0317-p1-v6"},{"type":"PUZZLE_SOLVED","id":"demo-0317-p2-v6"},{"type":"PUZZLE_SOLVED","id":"demo-0317-p3-v6"},{"type":"PUZZLE_SOLVED","id":"demo-0317-p4-v6"},{"type":"PUZZLE_SOLVED","id":"demo-0317-p5-v6"},{"type":"PUZZLE_SOLVED","id":"demo-0317-p6-v6"},{"type":"PUZZLE_SOLVED","id":"demo-0317-p7-v6"},{"type":"PUZZLE_SOLVED","id":"demo-0317-p8-v6"},{"type":"PUZZLE_SOLVED","id":"demo-0317-p9-v6"},{"type":"PUZZLE_SOLVED","id":"demo-0317-p10-v6"}]},"then":[{"type":"APPEND_MESSAGE","id":"demo-0317-chapter-complete"},{"type":"END_CASE","id":"ending-a"}]}],"endings":[{"id":"ending-a","title":"목록이 돌아왔다","text":"백업 복구 요청이 승인됐습니다. 7C21 사본이 작업 목록에 다시 나타났고 외부 전송은 실행되지 않았습니다.\n\n03:17은 빠른 PC의 표시였습니다. 취소된 요청과 내부 복제를 분리하니 빈 목록은 유출이나 삭제의 증거가 아니었습니다. 확정 서명부는 윤서가 자료실에서 사본을 인계했음을 보여 줍니다.\n\n윤서가 빈 책상으로 돌아와 말합니다. “자료도, 내가 한 일도 남아 있었네요.” 당신은 원본을 보존한 채 다음 근무자가 확인할 수 있는 목록을 남겼습니다.","revisitable":false},{"id":"ending-b","title":"기록보다 앞선 의심","text":"민재가 자리를 떠났다는 말과 PC의 시각만으로 자료 유출을 단정했습니다. 하지만 시계의 오차와 실제 전송 결과가 확인되지 않았습니다.\n\n이 결론에는 근거가 부족합니다. 조사로 돌아가 요청 로그와 처리 영수증을 대조하세요.","revisitable":true}],"hypotheses":[{"id":"h-no-transfer","label":"보존 사본으로 작업 목록 복구","endingId":"ending-a","requiredClues":["c-queue","c-receipt","demo-0317-clue-10a","demo-0317-clue-10b"]},{"id":"h-accuse","label":"민재가 자료를 외부로 전송했다.","endingId":"ending-b","requiredClues":[]}]}$case$::jsonb, true) ON CONFLICT (version_id) DO NOTHING;
INSERT INTO ghostdesk.case_versions(version_id, case_id, package, published) VALUES ('hotel-404-v6', 'hotel-404', $case${"schemaVersion":1,"engineVersion":"ghostdesk-core-1","caseId":"hotel-404","versionId":"hotel-404-v6","title":"자정의 404호","description":"닫힌 4층, 살짝 열린 404호와 흰 형체. 원격 점검 담당으로서 실제 출입과 보관 영상을 구분하고, 프런트가 현재 화면을 확인할 수 있도록 복구 인계를 마치세요.","estimatedMinutes":60,"contentWarning":"허구의 사건입니다. 긴장감 있는 상황·실종 암시가 있지만 잔혹한 묘사나 점프 스케어는 없습니다.","files":[{"id":"hotel-404-f0","type":"TEXT","title":"야간_인계.txt","parentId":null,"visible":true,"text":"닫힌 4층, 살짝 열린 404호와 흰 형체. 원격 점검 담당으로서 실제 출입과 보관 영상을 구분하고, 프런트가 현재 화면을 확인할 수 있도록 복구 인계를 마치세요.\n\n담당자가 남긴 메모\n저는 원격 야간 점검 담당입니다. 서린은 00:04에 프런트 화면에서 살짝 열린 404호 문과 카트를 미는 흰 옷의 사람을 봤습니다. 객실 키는 모두 프런트에 있습니다. 현장에 사람을 보내기 전에 오늘 실제로 열린 문과 영상의 출처부터 가려 주세요.\n\n업무 폴더에는 담당자가 기록을 대조해 정한 암호가 걸려 있습니다. 암호 규칙은 인계 메모와 각 업무 기록의 끝에 적어 두었습니다. 한 번 연 기록도 지우지 마세요.\n\n「객실 자료」 폴더 암호: 오늘 실제로 열린 문의 대장 번호-열린 뒤 자동 잠금까지의 초. 카메라 이름을 문 번호로 쓰지 마세요.","clueId":"hotel-404-c0"},{"id":"hotel-404-f1","type":"TEXT","title":"출입_이벤트.log","parentId":null,"visible":true,"text":"호텔 출입 제어기 / 오늘의 원본 이벤트\n\n00:03:58  장치 D-07  원격 개방 요청\n00:04:00  장치 D-07  개방 성공\n00:04:12  장치 D-07  자동 잠금\n\n오늘 4층 객실 장치 D-41~D-48의 개방 이벤트는 0건입니다.\n\n주의: 프런트에 보이는 카메라 이름은 출입 장치의 위치를 뜻하지 않습니다.","clueId":"hotel-404-c1"},{"id":"hotel-404-f2","type":"TEXT","title":"시설_장치대장.txt","parentId":null,"visible":true,"text":"시설팀 장치 대장 / 개보수 반영본\n\nD-03 → 0103 / 1층 창고\nD-07 → B204 / 지하 2층 세탁물 통로\nD-41 → 0401 / 4층 401호\nD-44 → 0404 / 4층 404호\n\n지하 통로는 배송 로봇 R17도 이용합니다. 층수 표시의 B는 지하층을 뜻하며 암호에 포함합니다.","clueId":"hotel-404-c2"},{"id":"hotel-404-f3","type":"IMAGE","title":"CAM-404_복도기록.mp4","parentId":null,"visible":true,"text":"복도 기록을 재현한 영상. 흰 작업복을 입은 인물이 카트를 밀며 앞으로 이동합니다. 404호 문은 살짝 열려 있습니다. 같은 영상에서 추출한 정지 화면은 이미지 자료에서 따로 확인할 수 있습니다.","clueId":"hotel-404-c3","assetId":"hotel","alt":"호텔 복도의 카트 위에 흰 시트가 접혀 있고 오른쪽에 노란 공사 덮개가 있는 녹화 장면.","observations":[{"label":"원본 기록","text":"06-12 14:32 / F-8821"},{"label":"복도 우측","text":"복도 오른쪽에 노란 공사용 덮개가 있습니다."},{"label":"중앙 카트","text":"접힌 흰 시트가 금속 카트에 여러 겹 놓여 있습니다."}]},{"id":"hotel-404-f4","type":"TEXT","title":"재생_진단서.txt","parentId":"hotel-404-stage-5","visible":false,"text":"CAM-404 재생 진단\n\n실시간 입력: 연결 끊김\n대체 소스: 06-12 보수공사 녹화\n재생 방식: 마지막 정상 영상 반복\n화면 위 LIVE 표지: 연결 상태와 무관하게 고정 표시\n\n오늘 00:04에도 F-8821 프레임이 재생됐습니다. 고정 표지 때문에 프런트 직원이 현재 영상으로 오인했습니다.","clueId":"hotel-404-c4"},{"id":"hotel-404-f5","type":"TEXT","title":"배송_완료증.txt","parentId":"hotel-404-stage-5","visible":false,"text":"세탁 배송 로봇 R17\n\n작업 번호: LINEN-0928\n00:04:00 B204 개방 신호 확인\n00:04:08 지하 세탁물 통로 통과\n00:06:21 세탁실 도착 / 시트 12묶음 인계\n\n오늘 4층 운행 명령 없음. 객실 손님 인식 기록 없음.\n\n프런트의 오래된 영상과 오늘의 문 개방은 별개의 사건이었습니다.","clueId":"hotel-404-c5"},{"id":"hotel-404-chat","type":"CHAT_LINK","title":"메신저","parentId":null,"visible":true,"text":""},{"id":"hotel-404-stage-1","type":"FOLDER","title":"객실 자료","parentId":null,"visible":true,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","puzzleId":"hotel-404-p1-v6"},{"id":"hotel-404-record-2","type":"TEXT","title":"화면_속_날짜.txt","parentId":null,"visible":false,"text":"시설 점검 메모\n\n오늘: 09-28\n6월 보수공사: 06-10 시작 / 06-15 종료\n복도 우측 노란 덮개: 보수공사 종료일 철거\n\n캡처에서 원본 기록과 프런트 화면 표지를 각각 확인하세요.\n\n시설 문서에서 쓰는 날짜는 같은 해입니다. 날짜 차이는 시작일 다음 날부터 종료일까지의 일수로 셉니다.\n\n「촬영 자료」 폴더 암호: 영상 원본 촬영일 네 자리-그 촬영 뒤 노란 덮개가 철거될 때까지 남은 일수. LIVE 표지가 아니라 원본에 찍힌 날짜를 읽습니다.","clueId":"hotel-404-record-clue-2"},{"id":"hotel-404-stage-2","type":"FOLDER","title":"촬영 자료","parentId":null,"visible":false,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","puzzleId":"hotel-404-p2-v6"},{"id":"hotel-404-record-3","type":"TEXT","title":"반복_구간_찾기.txt","parentId":null,"visible":false,"text":"프런트 모니터 점검 메모\n\n보관 영상에서는 인물이 카트를 밀고 한 방향으로 지나갑니다. 같은 이동이 되돌아오는 편집 경계를 찾아 주세요. 원본에서 추출한 정지 화면은 이미지 자료에 있습니다.\n\n진단용 관찰 구간: 재생 시작부터 30초 직전까지. 두 번째·세 번째 재생도 새 영상으로 세면 안 됩니다.\n\n「CCTV」 폴더 암호: 동일 장면이 처음 되돌아오기까지의 초-0초를 제외하고 30초 직전까지 시작될 재반복 횟수. 영상 전체 길이는 반복 간격이 아닙니다.","clueId":"hotel-404-record-clue-3"},{"id":"hotel-404-stage-3","type":"FOLDER","title":"CCTV","parentId":null,"visible":false,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","puzzleId":"hotel-404-p3-v6"},{"id":"hotel-404-record-4","type":"TEXT","title":"오늘의_이동_경로.txt","parentId":null,"visible":false,"text":"배송 장치 R17 / 09-28 위치 기록\n\n지점 1 · B204 문 · 00:04:08\n지점 2 · 세탁실 · 00:06:21\n지점 3 · 지하 적재대 · 00:03:42\n지점 4 · 지하 연결 통로 · 00:05:10\n\n모두 오늘의 장치 시계로 기록했습니다. 지점 번호는 지도에 붙인 번호이며 이동 순서가 아닙니다.\n\n「근무 기록」 폴더 암호: R17이 실제로 열린 문을 통과한 뒤 세탁실에 도착할 때까지 걸린 초. 적재대 출발 시각은 사용하지 않습니다.","clueId":"hotel-404-record-clue-4"},{"id":"hotel-404-stage-4","type":"FOLDER","title":"근무 기록","parentId":null,"visible":false,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","puzzleId":"hotel-404-p4-v6"},{"id":"hotel-404-record-5","type":"TEXT","title":"배송_수량_검산.txt","parentId":null,"visible":false,"text":"야간 세탁물 재고표 / 09-28\n\n적재 전 지하 창고: 20묶음\nR17 출발 후 창고: 8묶음\n세탁실 인수 전: 3묶음\n세탁실 인수 후: 15묶음\n\n점검 구간에 다른 반출입은 없었습니다. 창고 감소량과 세탁실 증가량이 일치하는지 확인한 뒤 완료증을 열어 주세요.\n\n「배송 내역」 폴더 암호: 창고에서 나간 묶음 수-그중 세탁실 증가량으로 확인되지 않는 묶음 수. 양쪽 재고를 독립적으로 계산합니다.","clueId":"hotel-404-record-clue-5"},{"id":"hotel-404-stage-5","type":"FOLDER","title":"배송 내역","parentId":null,"visible":false,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","puzzleId":"hotel-404-p5-v6"},{"id":"hotel-404-record-6a","type":"TEXT","title":"대체입력_목록.txt","parentId":null,"text":"연결이 끊겼을 때 재생하는 프로필 / 이미지 원문\n\nA / CAM-402 / 06-12 / 12초\nB / CAM-404 / 09-27 / 20초\nC / CAM-404 / 06-12 / 12초\n\n이 목록은 객실 배정표가 아니라 카메라별 보관 영상 선택표다.","visible":false,"clueId":"hotel-404-clue-6a"},{"id":"hotel-404-record-6b","type":"TEXT","title":"야간_접수메모.txt","parentId":null,"text":"서린의 점검 요청\n\n프런트에서 조사한 화면은 CAM-404다. 촬영일은 앞서 원본에서 확인했고, 같은 카트 움직임이 반복되는 간격도 직접 비교했다. 세 조건을 목록과 연결해 대체 소스를 특정해 달라.\n\n06-12 근무 대장: 4층 보수 구역 세탁물 회수 / 흰 작업복 착용. 인물의 얼굴이나 이름은 보관하지 않았다. 영상 속 404호는 실제 문이며 노란 덮개는 문 사이 공사 구역이다.\n\n대체 입력의 설정 번호는 카메라 숫자 세 자리, 촬영 월일 네 자리, 주기 두 자리를 하이픈으로 연결합니다. 표의 A·B·C는 행 표시일 뿐입니다.\n\n「장비 설정」 폴더 암호: 점검한 카메라-원본 촬영일-최초 반복 주기로 대체 입력의 설정 번호를 만듭니다. 서로 다른 프로필의 값을 섞지 않습니다.","visible":false,"clueId":"hotel-404-clue-6b"},{"id":"hotel-404-stage-6","type":"FOLDER","title":"장비 설정","parentId":null,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","visible":false,"puzzleId":"hotel-404-p6-v6"},{"id":"hotel-404-record-7a","type":"TEXT","title":"전환_패널.log","parentId":null,"text":"프런트 전환 패널 표시\n\n09-28 00:00:00 / CAM-404 입력 끊김\n09-28 00:00:01 / 대체 프로필 재생 시작\n\n패널 자체 시계를 사용한다. 카메라 원본에 찍힌 날짜와는 다른 시계다.","visible":false,"clueId":"hotel-404-clue-7a"},{"id":"hotel-404-record-7b","type":"TEXT","title":"패널_시계교정.txt","parentId":null,"text":"09-27 저녁 교정\n\n기준 23:50:00일 때 패널은 23:52:00을 표시했다. 다음 날 00:10까지 오차는 일정했다.\n\n자정을 넘겨 보정할 때 날짜도 함께 바뀐다. 화면 원본의 06-12는 촬영일이며 오늘 연결이 끊긴 날짜가 아니다.\n\n「네트워크」 폴더 암호: 실시간 입력이 끊긴 실제 날짜 네 자리-시각 네 자리. 패널 오차를 빼다가 자정을 넘으면 날짜도 바꿉니다.","visible":false,"clueId":"hotel-404-clue-7b"},{"id":"hotel-404-stage-7","type":"FOLDER","title":"네트워크","parentId":null,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","visible":false,"puzzleId":"hotel-404-p7-v6"},{"id":"hotel-404-record-8a","type":"TEXT","title":"시설팀_작업표.txt","parentId":null,"text":"기준시각 / 09-27\n\n조각 2 / 23:57:50 / 통신 중계기 교체 점검 승인\n조각 3 / 23:58:05 / 프런트 표시 검수 보류\n\n교체 작업표에는 대체 입력 확인은 완료, 프런트 표시 확인은 미완료로 남아 있다.\n\n「시설 관리」 폴더 암호: 교체 승인에서 입력 끊김까지의 초-입력 끊김에서 검수 보류까지의 초. 패널과 기준 시계를 맞춘 뒤 계산합니다.","visible":false,"clueId":"hotel-404-clue-8a"},{"id":"hotel-404-record-8b","type":"TEXT","title":"전환_추가조각.log","parentId":null,"text":"패널시각 / 09-28\n\n조각 4 / 00:00:00 / 실시간 입력 끊김\n조각 1 / 00:00:01 / 대체 영상 시작\n\n패널은 기준시각보다 2분 빠르다. 표시 검수란 대체 재생 때 LIVE 표지를 제거했는지 사람이 확인하는 절차다.","visible":false,"clueId":"hotel-404-clue-8b"},{"id":"hotel-404-stage-8","type":"FOLDER","title":"시설 관리","parentId":null,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","visible":false,"puzzleId":"hotel-404-p8-v6"},{"id":"hotel-404-record-9a","type":"TEXT","title":"재연결_검수기준.txt","parentId":null,"text":"현재 입력 판별\n\n조건 1: 원본 촬영 시각이 점검 구간 09-28 00:12 이후다.\n조건 2: 5초 뒤 수신한 원본 번호가 앞선 번호보다 증가한다.\n\nLIVE 글자나 복도에 사람이 없다는 사실은 이 두 조건을 대신하지 못한다.\n\n「복구 자료」 폴더 암호: 현재 입력 조건을 만족하는 쌍의 뒤쪽 원본 번호-초당 번호 증가량. 움직인다는 이유만으로 과거 영상은 통과시키지 않습니다.","visible":false,"clueId":"hotel-404-clue-9a"},{"id":"hotel-404-record-9b","type":"TEXT","title":"수신_쌍기록.txt","parentId":null,"text":"5초 간격으로 보관한 원본 두 장의 메타데이터\n\nA / 06-12 14:32:00, 번호 8821 → 06-12 14:32:05, 번호 8941 / LIVE\nB / 09-28 00:12:10, 번호 9101 → 09-28 00:12:15, 번호 9221 / LIVE 없음\nC / 09-28 00:12:10, 번호 9101 → 09-28 00:12:10, 번호 9101 / LIVE\n\n이는 점검 뒤의 수신 기록이며 처음 보았던 6월 영상의 설명을 바꾸지 않는다.","visible":false,"clueId":"hotel-404-clue-9b"},{"id":"hotel-404-stage-9","type":"FOLDER","title":"복구 자료","parentId":null,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","visible":false,"puzzleId":"hotel-404-p9-v6"},{"id":"hotel-404-record-10a","type":"TEXT","title":"표시_배선설명.txt","parentId":null,"text":"프런트 표시 구조\n\n영상 영역: 카메라 또는 대체 프로필 입력을 표시\nLIVE 글자: 모니터 위에 붙인 고정 표지. 입력과 연결되지 않음\n출입 알림: 별도 D-07 제어기에서 수신\n\n세 항목은 같은 화면 주변에 보여도 같은 사건을 뜻하지 않는다.","visible":false,"clueId":"hotel-404-clue-10a"},{"id":"hotel-404-record-10b","type":"TEXT","title":"시설팀_확인회신.txt","parentId":null,"text":"시설팀 / 최종 인계 승인 대기\n\n교체 점검은 MT-0927로 확인됐습니다. 현재 입력 후보를 받았지만 프런트 복구 인계는 아직 서명하지 않았습니다. 과거 복도와 오늘 열린 문을 분리하고, 실시간임을 검수한 입력으로 전환해야 합니다.\n\n표시 처리 코드\nFIXED: 기존 LIVE 고정 표지 유지\nSTAMP: 마지막 수신 원본의 촬영 시각 표시\n\n고정 표지는 입력 상태와 연결되지 않습니다. 인계 승인을 하면 검수된 현재 입력을 연결하고 선택한 표시 방식을 적용합니다.\n\n「인수인계」 폴더 암호: 표시 처리 코드-오늘 열린 문-대체 영상 촬영일 네 자리-검수된 현재 입력의 마지막 원본 번호. 이 조합으로 프런트 복구 인계를 승인합니다.","visible":false,"clueId":"hotel-404-clue-10b"},{"id":"hotel-404-stage-10","type":"FOLDER","title":"인수인계","parentId":null,"text":"잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.","visible":false,"puzzleId":"hotel-404-p10-v6"}],"clues":[{"id":"hotel-404-c0","title":"야간_인계.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"hotel-404-c1","title":"출입_이벤트.log","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"hotel-404-c2","title":"시설_장치대장.txt","description":"원본 기록과 인계 메모를 대조해 확인할 자료입니다."},{"id":"h