,"when":{"type":"ALL","conditions":[{"type":"PUZZLE_SOLVED","id":"monday-loop-p1-v6"},{"type":"PUZZLE_SOLVED","id":"monday-loop-p2-v6"},{"type":"PUZZLE_SOLVED","id":"monday-loop-p3-v6"},{"type":"PUZZLE_SOLVED","id":"monday-loop-p4-v6"},{"type":"PUZZLE_SOLVED","id":"monday-loop-p5-v6"},{"type":"PUZZLE_SOLVED","id":"monday-loop-p6-v6"},{"type":"PUZZLE_SOLVED","id":"monday-loop-p7-v6"},{"type":"PUZZLE_SOLVED","id":"monday-loop-p8-v6"},{"type":"PUZZLE_SOLVED","id":"monday-loop-p9-v6"},{"type":"PUZZLE_SOLVED","id":"monday-loop-p10-v6"}]},"then":[{"type":"APPEND_MESSAGE","id":"monday-loop-chapter-complete"},{"type":"END_CASE","id":"monday-loop-good"}]}],"endings":[{"id":"monday-loop-good","title":"수요일의 목록","text":"새 관측 목록이 열렸습니다. 09-16의 1086 묶음은 검증된 사본으로 연결됐고, 세 날의 부표 원본은 읽기 전용으로 남았습니다. R-086의 접수와 후속 인계도 같은 요청으로 연결됐습니다.\n\n세 번의 월요일은 같은 화면을 불러온 세 번의 부팅이었습니다. 종이 노트와 해초가 붙은 밧줄, 독립된 부표는 실제 시간이 흘렀음을 기록했습니다.\n\n나루는 안내문의 첫 줄을 읽고 창밖을 봅니다. “수요일이네.” 화면을 고치기 위해 바다의 기록을 지울 필요는 없었습니다.","revisitable":false},{"id":"monday-loop-retry","title":"같은 문장이 같은 하루는 아니다","text":"같은 인사와 날짜를 보고 시간이 반복된다고 판단했습니다. 하지만 그 결론은 줄어든 우유와 달라진 관측 번호를 설명하지 못합니다.\n\n비공개 기록의 복원 작업일지와 외부 관측함의 원본 날짜를 끝까지 대조해 주세요.","revisitable":true}],"hypotheses":[{"id":"monday-loop-truth","label":"원본 보존과 새 관측 목록 연결","endingId":"monday-loop-good","requiredClues":["monday-loop-c3","monday-loop-c4","monday-loop-final-clue","monday-loop-clue-10a","monday-loop-clue-10b"]},{"id":"monday-loop-guess","label":"섬의 시간 자체가 월요일에 갇혀 같은 하루가 반복되고 있다.","endingId":"monday-loop-retry","requiredClues":[]}]}$case$::jsonb, true) ON CONFLICT (version_id) DO NOTHING;
